/**
 * A typed Angular surface for every element this package defines.
 *
 * Generated, and that is the point: a hand-written directive is a parallel structure over
 * the manifest with nothing watching it, so an attribute added to an element would be
 * typed in React, Vue and Svelte — which derive from the registry — and silently missing
 * here. That happened, which is why this file is generated now.
 *
 * Outputs emit the event's DETAIL, not the `CustomEvent`, because
 * `(selectChange)="pick($event.value)"` is the Angular idiom. Reach the event itself with
 * a plain host listener when you need `stopPropagation`.
 */
import {
    Directive,
    ElementRef,
    EventEmitter,
    HostListener,
    Input,
    Output,
    booleanAttribute,
    inject,
} from '@angular/core';
import { applyElementProps } from '@aparte/core';
import type {
    AparteModelChangeEventDetail,
} from '@aparte/core';

/**
 * Writes one declared attribute onto the host element.
 *
 * `applyElementProps` is core's own rule, reused rather than reimplemented: a primitive
 * goes through `setAttribute`, `true` becomes the empty presence attribute,
 * `false`/`null`/`undefined` remove it, and only a value an attribute cannot carry is
 * handed over as a property.
 */
@Directive()
abstract class AparteElementBase {
    protected readonly host = inject(ElementRef<HTMLElement>);

    protected write(name: string, value: unknown): void {
        applyElementProps(this.host.nativeElement, { [name]: value });
    }
}

/** `<aparte-model-selector>` — Selects an AI provider and a model. Renders an `<aparte-select>` with providers grouped into `<aparte-optgroup>`s — a single provider renders a flat list — which is what makes the BYOK pattern possible without core knowing about any vendor. */
@Directive({ selector: 'aparte-model-selector', standalone: true })
export class AparteModelSelectorDirective extends AparteElementBase {
    /** Writes the selection back through the config, so it survives a reload. */
    @Input({ transform: booleanAttribute }) set persist(v: boolean) { this.write('persist', v); }
    /** Selects the first model as soon as one is available. */
    @Input({ transform: booleanAttribute }) set autoSelect(v: boolean) { this.write('auto-select', v); }
    /** Adds the dropdown's filter field. */
    @Input({ transform: booleanAttribute }) set searchable(v: boolean) { this.write('searchable', v); }
    /** Overrides the text shown while nothing is selected. */
    @Input() set placeholder(v: string | undefined) { this.write('placeholder', v); }

    /** The provider or the model changed; carries both ids. */
    @Output() readonly modelChange = new EventEmitter<AparteModelChangeEventDetail>();

    @HostListener('aparte-model-change', ['$event'])
    protected onModelChange(e: CustomEvent<AparteModelChangeEventDetail>): void { this.modelChange.emit(e.detail); }
}

